// symbol-dispose-prelude: bun build --banner for every SDK bundle; the build
// scripts grep for this line's tag. Runs before any module body. bun lowers
// `using` to a helper that keys disposal on the registry symbol when the
// well-known one is missing, while disposable objects key on the well-known
// global directly; on engines without a native `Symbol.dispose` (Safari/iOS,
// Firefox ESR, `node:vm` contexts on Node <=22 such as Jest's `node`
// environment and vitest's vm pools, and Node before 18.18 / 20.4) the two
// disagree and every lowered `using` throws. Registering both symbols first
// makes the keys agree; a no-op where they are native, and a locked-down
// `Symbol` (SES lockdown) keeps today's behaviour instead of failing to load.
if (typeof Symbol.dispose !== 'symbol') {
  try {
    Symbol.dispose = Symbol.for('Symbol.dispose')
  } catch {}
}
if (typeof Symbol.asyncDispose !== 'symbol') {
  try {
    Symbol.asyncDispose = Symbol.for('Symbol.asyncDispose')
  } catch {}
}
